  // reports — keys the dev warning surfaced
  "report.sales.by-salesperson.description": "أداء مندوبي المبيعات في الفترة: عدد الفواتير، الإجمالي المُفوتر، خصومات العروض الممنوحة، والمتبقي على العملاء. الفواتير غير المنسوبة لمندوب تظهر في صف «غير محدد» حتى يساوي إجمالي التقرير إجمالي مبيعات الفترة.",
  "report.field.van-sales.description": "ملخص رحلات المندوبين في الفترة: المحمّل من المخزون، والمرتجع عند التسوية، والنقدية المسجلة في الميدان، وفرق النقدية عند التسوية. الكميات مجمّعة عبر كل الأصناف، و«المنصرف» هو المحمّل ناقص المرتجع (يشمل المباع وأي عجز). الرحلات غير المسواة تظهر بخانات فارغة في أعمدة التسوية.",
  "report.inventory.expiring.description": "الدفعات التي لها تاريخ صلاحية مرتبة بالأقرب انتهاءً — وهو نفس ترتيب الصرف (FEFO) الذي يتبعه المخزون.",
